def test_insert_megillah_playlist(playlist_repo):
    p = Playlist(
        name="שיר השירים",
        book="Song of Songs",
        playlist_type=PlaylistType.MEGILLAH,
        chapter_start=1,
        verse_start=1,
        chapter_end=8,
        verse_end=14,
    )
    inserted = playlist_repo.insert(p)
    assert inserted.id is not None

    fetched = playlist_repo.get_by_id(inserted.id)
    assert fetched.playlist_type == PlaylistType.MEGILLAH
    assert fetched.book == "Song of Songs"


